package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import com.mongodb.client.MongoClients;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import org.icu.sepsis.application.Store;import org.icu.sepsis.domain.Domain.Patient;import org.springframework.data.mongodb.core.MongoTemplate;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
@EnabledIfEnvironmentVariable(named="LOCAL_MONGO_TESTS",matches="1") class LocalMongoSpecialtyTest {
 @Test void persistedSpecialtyFactsAreScopedVersionedAndRevocable(){String name="icu_sepsis_devtest_"+UUID.randomUUID().toString().replace("-","");try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){boolean own=false;try{assertFalse(client.listDatabaseNames().into(new ArrayList<>()).contains(name));own=true;var db=new MongoTemplate(client,name);var service=new SpecialtyEvidenceService(new Store(db,"TEST",new ObjectMapper().registerModule(new JavaTimeModule())));var p=new Patient();p.id="synthetic-p";p.encounterId="stay";p.department="TEST";Instant now=Instant.parse("2026-11-20T08:00:00Z");var req=new SpecialtyEvidenceService.Request();req.encounterId=p.encounterId;req.reason="Synthetic bedside review";var adult=new SpecialtyEvidenceService.Value();adult.flag=true;adult.observedAt=now;adult.reference="Synthetic assessment";req.values.put("adult",adult);var rass=new SpecialtyEvidenceService.Value();rass.number=-4d;rass.unit="score";rass.observedAt=now;rass.reference="Synthetic RASS";req.values.put("rass",rass);var first=service.record(p,"delirium",req,"doctor",now);assertThrows(org.icu.sepsis.api.ApiException.class,()->service.record(p,"delirium",req,"doctor",now));var packet=service.assess(p,now,List.of(),Map.of());var modules=(List<Map<String,Object>>)packet.get("modules");assertEquals("not_assessable",modules.stream().filter(m->m.get("key").equals("delirium")).findFirst().orElseThrow().get("status"));p.birthDate=java.time.LocalDate.of(2010,1,1);var ageConflict=(List<Map<String,Object>>)service.assess(p,now,List.of(),Map.of()).get("modules");assertEquals("unknown",ageConflict.stream().filter(m->m.get("key").equals("delirium")).findFirst().orElseThrow().get("status"));p.birthDate=null;var observed=new org.icu.sepsis.domain.Domain.Observation();observed.patientId=p.id;observed.encounterId=p.encounterId;observed.department=p.department;observed.parameterCode="RASS";observed.value=0d;observed.unit="score";observed.qualityStatus="valid";observed.eventTime=now;var conflicted=(List<Map<String,Object>>)service.assess(p,now,List.of(observed),Map.of()).get("modules");assertEquals("unknown",conflicted.stream().filter(m->m.get("key").equals("delirium")).findFirst().orElseThrow().get("status"));p.encounterId="other";assertTrue(((List<Map<String,Object>>)service.assess(p,now,List.of(),Map.of()).get("modules")).stream().allMatch(m->"unknown".equals(m.get("status"))));p.encounterId="stay";req.expectedId=first.id;req.withdrawn=true;req.values=Map.of();service.record(p,"delirium",req,"doctor",now);assertTrue(((List<Map<String,Object>>)service.assess(p,now,List.of(),Map.of()).get("modules")).stream().allMatch(m->"unknown".equals(m.get("status"))));assertEquals(2,db.findAll(SpecialtyEvidenceService.Record.class).size());System.out.println("LOCAL_SPECIALTY_SYNTHETIC: scoped review, stale-write rejection and withdrawal verified");}finally{if(own&&name.matches("icu_sepsis_devtest_[a-f0-9]{32}"))client.getDatabase(name).drop();}}}
}
